import {QRCodeSVG} from "qrcode.react";
import React from "react";
import {Box, styled, Typography} from "@mui/material";


export const RootDiv = styled("div", {
    name: 'Qr',
    slot: 'root'
})(({theme}) => ({
    padding: 4,
}))


export const Qr = (props: { url: string, text?: React.ReactNode }) => {

    return <RootDiv>
        <div style={{
            borderColor: '#FFFFFF',
            borderWidth: 2,
            borderStyle: "solid",
            height: 124,
            width: 124,
        }}>
            <QRCodeSVG
                size={120}
                value={props.url}
            />
        </div>
        <div style={{textAlign: "center"}}>{props.text ||
            <Typography style={{fontSize: "0.7rem"}}>Открыть <br/> в телефоне</Typography>}</div>
    </RootDiv>
}

