import * as React from 'react';
import {
    AppBar,
    Container,
    IconButton,
    Tabs,
    Tab,
    Typography,
    Box,
    Button,
    List,
    ListItem,
    ListItemButton,
    ListItemText,
    Stack,
    Paper,
    Card,
    CardHeader,
    CardContent,
    CardMedia,
    CardActions,
    useTheme,
    Grid,
    Badge
} from "@mui/material";
import Divider from '@mui/material/Divider';
import {generatePath, Link, useNavigate} from "react-router";
import axios, {AxiosResponse} from "axios";
import {baseUrl, excursionsUrl, mainUrl, topicUrl} from "../../config/consts";
import {IPageResponse} from "../../common/response";
import {Excursion} from "./model";
import {useContext, useEffect, useState} from "react";
import {Header} from "../../components/header/header-component";
import {ApplicationBar} from "../../components/appbar/application-bar";
import {baseRoute, excursionItemRoute} from "../../config/routes";
import {DirectionsBus, DirectionsWalk} from "@mui/icons-material";
import {StyledBadge} from "../../components/custom-badge/custom-badge.component";
import {ApplicationFooter} from "../../components/appbar/application-footer";
import {Topic} from "../excursion-item-page/model";
import {Main} from "../../components/main-context/main";
import {Helmet} from "react-helmet";
import {prepareTest} from "../../utils/text-utils";
import {MainContext} from "../../components/main-context/main-context";
import {MyHelmet} from "../../components/helmet/my-helmet.component";

export interface ExcursionPageProps {

}


const ExcursionPage = (props: ExcursionPageProps) => {

    const navigate = useNavigate();

    const theme = useTheme();

    const ctx = useContext(MainContext);

    const [data, setData] = useState<IPageResponse<Excursion>>({
        data: [],
        meta: {
            pagination: {
                page: 0,
                total: 0,
                pageCount: 0,
                pageSize: 0
            }
        }
    });

    useEffect(() => {
        axios.get(excursionsUrl, {
            params: {
                populate: ["cover", "places"],
            }
        }).then((response: AxiosResponse<IPageResponse<Excursion>>) => {
            const data = response.data;
            axios.get(mainUrl).then((resp) => {
                const mainData: Main = resp.data as Main;
                const idxMap = new Map<number, number>();
                (mainData?.data?.attributes?.excursions?.data || []).forEach((it, idx) => {
                    idxMap.set(it.id, idx + 1);
                })
                data.data.sort((t1, t2) => (idxMap.get(t1.id) || 0) - (idxMap.get(t2.id) || 0))
                setData(data)
            }).catch((reason) => {
                setData(data);
            })
        }).catch((error) => navigate(baseRoute));
    }, [])

    return <div>
        <MyHelmet title={'Экскурсии'}/>
        <div style={{position: "relative"}}>
            <div style={{
                opacity: 0.03,
                position: "absolute",
                height: "100%",
                width: "100%",
                backgroundImage: "url(https://sun1-16.userapi.com/impg/7MVdJ7k4B_ik2HbKWyM68zx4gtGqYCNN1kJjaQ/p1oqti9iNfs.jpg?size=1600x1068&quality=96&sign=7fc8494393646b3ff6e56456854acce9&type=album)"
            }}>

            </div>
            <ApplicationBar/>
            <Header title={"Экскурсии"}/>
        </div>
        <Stack spacing={4} sx={{
            [theme.breakpoints.down("md")]: {paddingTop: 4},
            [theme.breakpoints.down("sm")]: {paddingTop: 2},
            paddingBottom: 4,
            paddingTop: 8
        }}>
            {(data.data || []).map((it, idx) => <Paper key={idx} style={{background: "none"}}>
                <Container>
                    <Card sx={{flex: 1, display: {xs: "none", sm: "none", md: "flex"}, cursor: "pointer"}}
                          onClick={() => navigate(generatePath(excursionItemRoute, {id: `${it.id}`}))}>
                        <CardMedia
                            component="img"
                            sx={{flex: 1, width: "40%"}}
                            image={baseUrl + (it.attributes?.cover?.data?.attributes?.formats?.medium?.url || '')}
                        />
                        <CardContent
                            sx={[{
                                display: "flex",
                                flexDirection: "column",
                                flex: 2,
                                width: "50%"
                            }]}>


                            <div>

                                <Typography variant={"h5"} padding={4}>
                                    <StyledBadge color={"primary"}
                                                 badgeContent={it.attributes?.places?.data?.length}>
                                        {it.attributes?.caption || ''}
                                    </StyledBadge>
                                </Typography>

                            </div>


                            <Divider/>
                            <Typography variant={"subtitle1"} textAlign={"left"} color={"textSecondary"} paddingTop={4}
                                        paddingBottom={4}>
                                {it.attributes?.description || ''}
                            </Typography>
                            <Grid container rowSpacing={2}>
                                {(it.attributes.type || '') &&
                                    <Grid size={{lg: 4, md: 12, sm: 12, xs: 12}} container spacing={1}
                                          alignItems="center"
                                          flexWrap={"nowrap"}>
                                        <Grid>
                                            <Typography variant={"subtitle1"} color={"textSecondary"}>
                                                Тип:
                                            </Typography>
                                        </Grid>
                                        <Grid>
                                            <Typography variant="subtitle1" color={"textSecondary"}>
                                                {it.attributes.type}
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                }
                                {(it.attributes.distance || '') &&
                                    <Grid size={{lg: 4, md: 12, sm: 12, xs: 12}} container spacing={1}
                                          alignItems="center"
                                          flexWrap={"nowrap"}>
                                        <Grid>
                                            <Typography variant={"subtitle1"} color={"textSecondary"}>
                                                Дистанция:
                                            </Typography>
                                        </Grid>
                                        <Grid>
                                            <Typography variant="subtitle1" color={"textSecondary"}>
                                                {it.attributes.distance || ''}
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                }
                            </Grid>
                            <CardActions sx={{paddingTop: 4, paddingLeft: 0,}}
                                         onClick={() => navigate(generatePath(excursionItemRoute, {id: `${it.id}`}))}>
                                <Button sx={{padding: 0}}>Показать</Button>
                            </CardActions>
                        </CardContent>
                    </Card>
                    <Card sx={{
                        [theme.breakpoints.down("md")]: {display: "flex"},
                        display: "none",
                        width: "100%",
                        flex: 1,
                        flexDirection: "column"
                    }} onClick={() => navigate(generatePath(excursionItemRoute, {id: `${it.id}`}))}>
                        <CardContent
                            sx={[{
                                display: "block",
                                flexDirection: "column",
                                width: "100%"
                            }]}>

                            <div>
                                <Typography variant={"h4"} textAlign={"center"} padding={4}>
                                    <StyledBadge color={"primary"}
                                                 badgeContent={it.attributes?.places?.data?.length}>
                                        {it.attributes?.caption || ''}
                                    </StyledBadge>
                                </Typography>
                            </div>
                        </CardContent>
                        <CardMedia
                            component="img"
                            sx={{width: "100%"}}
                            image={baseUrl + (it.attributes?.cover?.data?.attributes?.formats?.medium?.url || '')}
                        />
                        <CardContent
                            sx={[{
                                display: {sm: "block", md: "flex"},
                                flexDirection: "column",
                                width: "100%"
                            }]}>

                            <Typography variant={"subtitle1"} textAlign={"left"} paddingTop={4} paddingBottom={4}
                                        color={"textSecondary"}>
                                {it.attributes?.description || ''}
                            </Typography>
                            <Grid container paddingBottom={4} rowSpacing={2}>
                                {(it.attributes.type || '') &&
                                    <Grid size={{lg: 4, md: 4, sm: 4, xs: 12}} container spacing={1}
                                          alignItems="center"
                                          flexWrap={"nowrap"}>
                                        <Grid>
                                            <Typography variant={"subtitle1"} color={"textSecondary"}>
                                                Тип:
                                            </Typography>
                                        </Grid>
                                        <Grid>
                                            <Typography variant="subtitle1" color={"textSecondary"}>
                                                {it.attributes.type}
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                }
                                {(it.attributes.distance || '') &&
                                    <Grid size={{lg: 8}} container spacing={1}
                                          alignItems="center"
                                          flexWrap={"nowrap"}>
                                        <Grid>
                                            <Typography variant={"subtitle1"} color={"textSecondary"}>
                                                Дистанция:
                                            </Typography>
                                        </Grid>
                                        <Grid>
                                            <Typography variant="subtitle1" color={"textSecondary"}>
                                                {it.attributes.distance || ''}
                                            </Typography>
                                        </Grid>
                                    </Grid>
                                }
                            </Grid>

                            <CardActions sx={{padding: 0, paddingLeft: 0}}>
                                <Button sx={{paddingLeft: 0}}
                                        onClick={() => navigate(generatePath(excursionItemRoute, {id: `${it.id}`}))}>Показать</Button>
                            </CardActions>
                        </CardContent>

                    </Card>
                </Container>
            </Paper>)}
        </Stack>
        <ApplicationFooter/>
    </div>
}

export default ExcursionPage;