import {Helmet} from "react-helmet";
import React, {useEffect} from "react";

export const MyHelmet = (props:{title?: string})=>{

    useEffect(()=>{
        document.title = 'Гид по Омску'+(props.title? '. '+props.title: '');
    },[props.title])

    return <Helmet>
        <title>{'Гид по Омску'+(props.title? '. '+props.title: '')}</title>
        <meta name="title" content="Гид по Омску" data-react-helmet="true"/>
    </Helmet>
}