import {Link, LinkProps} from "react-router";
import {styled} from "@mui/material";
import {palleteTheme} from "../../theme/dark.theme";

const MyLinkRoot = styled('div', {
    name: 'MyLink', // The component name
    slot: 'root', // The slot name
})(({ theme }) => ({
   color: "inherit",
    "& a":{
        textDecoration: "none",
        textTransform: "uppercase",
        padding: "6px 8px",
        fontSize: "0.875rem",
        color: palleteTheme.palette.primary.main,
        "&:hover":{
            backgroundColor: `${palleteTheme.palette.primary.main}10`
        }
    }
}));


export const MyLink = (props:LinkProps)=>{
    return <MyLinkRoot>
        <Link {...props}/>
    </MyLinkRoot>
}