import * as React from 'react';
import {useContext, useEffect, useMemo, useRef, useState} from 'react';
import {
    Box,
    Button,
    Card,
    CardActions,
    CardContent,
    CardMedia,
    Container,
    Grid, keyframes,
    Paper,
    Stack, styled,
    Typography,
    useTheme
} from "@mui/material";
import Divider from '@mui/material/Divider';
import {generatePath, Link, useNavigate} from "react-router";
import {
    aboutRouteUrl,
    baseRoute,
    eventsRouteUrl,
    excursionRoute,
    topicPlaceRoute, topicRouteUrl,
    topicsRouteUrl
} from "../../config/routes";
import {baseUrl, topicItemUrl} from "../../config/consts";
import {ApplicationBar} from "../../components/appbar/application-bar";
import {MainContext} from "../../components/main-context/main-context";
import {prepareTest} from "../../utils/text-utils";
import {ReactComponent as Star} from "../../svg/star.svg";
import {IResponse} from "../../common/response";
import {Topic} from "../excursion-item-page/model";
import axios, {AxiosResponse} from "axios";
import {generatePathApp} from "../../utils/genpath-util";
import {getRandomItems} from "../../utils/random-utils";
import {ApplicationFooter} from "../../components/appbar/application-footer";
import {t} from '../../i18n';
import {MyLink} from "../../components/link/link-component";
import {Helmet} from "react-helmet";
import {MyHelmet} from "../../components/helmet/my-helmet.component";


export interface MainPageProps {

}

const shrink = keyframes`
  0% {
        width: 100% ;
                opacity: 1 ;
}
 5%{
     opacity: 1 ;
 }
70% {
  opacity: 1 ;
}
100% {
    width: 120%;
        opacity: 0;
}
`;

const notAnimated = keyframes`
    0% {
       opacity: 0 ;
    }
 
    50% {
      opacity: 0 ;
    }
     70% {
      opacity: 0.7 ;
    }
    100% {
        opacity: 1;
    }
`;


type DivProps = {
    imageUrl: string;
    animated: boolean
};

const Root = styled('div', {
    name: 'MainPageRoot', // The component name
    slot: 'root', // The slot name
})<DivProps>(({theme, imageUrl, animated}) => ({
    animation: animated ? `${shrink} 5s linear` : `${notAnimated} 5s linear`,
    backgroundSize: "cover",
    height: "100%",
    width: "100%",
    position: 'absolute',
    backgroundImage: !imageUrl ? "url(https://sun1-16.userapi.com/impg/7MVdJ7k4B_ik2HbKWyM68zx4gtGqYCNN1kJjaQ/p1oqti9iNfs.jpg?size=1600x1068&quality=96&sign=7fc8494393646b3ff6e56456854acce9&type=album)" : `url(${baseUrl}/${imageUrl})`,
backgroundPosition: "center",
}))
;


const MainPage = (props: MainPageProps) => {

    const navigate = useNavigate();

    const ctx = useContext(MainContext);

    const theme = useTheme();

    const [imgIndex, setImgIndex] = useState(0);

    const total = (ctx.pictures || []).length;

    useEffect(() => {

        if (total) {
            const r = setInterval(() => {
                setImgIndex((prev) => (prev + 1) % total)
            }, 5000);
            return () => clearInterval(r);
        }
        return () => {
        };
    }, [ctx.pictures])

    const mainTopicId = ctx.mainTopicId;
    const mainTopicId2 = ctx.mainTopicId2;

    const [mainTopic, setMainTopic] = useState<IResponse<Topic> | null>(null);
    const [mainTopic2, setMainTopic2] = useState<IResponse<Topic> | null>(null);

    const cardsRef = useRef<Map<number, HTMLElement | null>>(new Map<number, HTMLElement>());


    const topics = useMemo(() => {
        return getRandomItems(mainTopic?.data?.attributes.places.data || [], Number(ctx.texts.get("page.main.sections.section1.cards.count") || 6));
    }, [!mainTopic?.data?.attributes.places.data, ctx.texts.get("page.main.sections.section1.cards.count")])


    const topics2 = useMemo(() => {
        return getRandomItems(mainTopic2?.data?.attributes.places.data || [], Number(ctx.texts.get("page.main.sections.section2.cards.count") || 6));
    }, [!mainTopic2?.data?.attributes.places.data, ctx.texts.get("page.main.sections.section2.cards.count")])

    useEffect(() => {
        if (mainTopicId < 0) {
            setMainTopic(null);
            return;
        }
        axios.get(generatePathApp(topicItemUrl, {id: `${mainTopicId}`}), {
            params: {
                populate: "cover"
            }
        }).then((response: AxiosResponse<IResponse<Topic>>) => {
            const data = response.data;
            setMainTopic(data);
        }).catch((error) => navigate(baseRoute));
    }, [mainTopicId])


    useEffect(() => {
        if (mainTopicId2 < 0) {
            setMainTopic2(null);
            return;
        }
        axios.get(generatePathApp(topicItemUrl, {id: `${mainTopicId2}`}), {
            params: {
                populate: "cover"
            }
        }).then((response: AxiosResponse<IResponse<Topic>>) => {
            const data = response.data;
            setMainTopic2(data);
        }).catch((error) => navigate(baseRoute));
    }, [mainTopicId2])

    return <div>
        <MyHelmet title={''}/>
        <div style={{position: "relative"}}>
            <div style={{
                position: "absolute",
                height: "100%",
                width: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                overflow: "hidden"
            }}>
                <Root key={total ? (imgIndex + 1) % total : -1}
                      imageUrl={(ctx.pictures || [])[total ? (imgIndex + 1) % total : -1]?.image?.data?.attributes?.url || ''}
                      animated={false}/>
                <Root key={imgIndex} imageUrl={(ctx.pictures || [])[imgIndex]?.image?.data?.attributes?.url || ''}
                      animated={true}/>
            </div>
            <ApplicationBar/>
            <Stack spacing={2} sx={{minHeight: 700, justifyContent: "center"}}>
                <Paper sx={{background: "unset"}}>
                    <Container>
                        <Card sx={{
                            background: "unset !important;",
                            borderRadius: 4,
                            backdropFilter: "blur(1px)",
                            paddingTop: 4,
                            paddingBottom: 4
                        }}>
                            <CardContent
                                sx={{display: "flex", flexDirection: "column", width: "100%", alignContent: "center"}}>
                                <Typography variant={"h1"} textAlign={"center"} padding={4}
                                            sx={{fontWeight: 700, color: "#FFFFFF", fontSize: "9rem"}}>
                                    {prepareTest(ctx.texts.get("page.main.title.primary")) || 'Гид по Омску'}
                                </Typography>
                                <Box sx={{display: "flex", justifyContent: "center"}}>
                                    <Paper sx={{padding: 0, background: "unset"}}>
                                        <Typography variant={"body2"} textAlign={"center"} padding={0} paddingLeft={1}
                                                    paddingRight={1}
                                                    sx={{
                                                        fontWeight: 700,
                                                        color: "#FFFFFF",
                                                        fontSize: "2rem",
                                                        [theme.breakpoints.down('md')]: {
                                                            paddingLeft: 2,
                                                            paddingRight: 2
                                                        }
                                                    }}
                                                    color={"textSecondary"}>

                                            {prepareTest(ctx.texts.get("page.main.title.secondary")) ||
                                                <span>Влюбляем в город моментально!</span>}
                                        </Typography>
                                    </Paper>
                                </Box>
                            </CardContent>
                        </Card>
                    </Container>
                </Paper>
            </Stack>
        </div>
        <Container>
            <Grid container={true} sx={{width: "100%"}} rowSpacing={4} columnSpacing={4} paddingTop={8}
                  paddingBottom={8}>
                <Grid size={{lg: 6, md: 12, sm: 12, xs: 12}}>
                    <Card sx={{flex: 1, cursor: "pointer"}} onClick={() => navigate(excursionRoute)}>
                        <CardContent
                            sx={{display: "flex", flexDirection: "column", width: "100%", alignContent: "center"}}>

                            <Typography variant={"h4"} textAlign={"left"} padding={0}>
                                Экскурсии
                            </Typography>
                            <Typography variant={"subtitle2"} textAlign={"left"} paddingTop={4} paddingBottom={0}
                                        color={"textSecondary"}>
                                {prepareTest(ctx.texts.get("menu.excursions.description"))}
                            </Typography>

                        </CardContent>
                        <CardActions>
                            <Link to={excursionRoute}>Показать</Link>
                        </CardActions>
                    </Card>
                </Grid>
                <Grid size={{lg: 6, md: 12, sm: 12, xs: 12}}>
                    <Card sx={{flex: 1, cursor: "pointer"}} onClick={() => navigate(topicsRouteUrl)}>
                        <CardContent
                            sx={{display: "flex", flexDirection: "column", width: "100%", alignContent: "center"}}>
                            <Typography variant={"h4"} textAlign={"left"} padding={0}>
                                Достопримечательности
                            </Typography>
                            <Typography variant={"subtitle2"} textAlign={"left"} paddingTop={4} paddingBottom={0}
                                        color={"textSecondary"}>
                                {prepareTest(ctx.texts.get("menu.topics.description"))}
                            </Typography>
                        </CardContent>
                        <CardActions>
                            <Link to={topicsRouteUrl}>Показать</Link>
                        </CardActions>
                    </Card>
                </Grid>
                <Grid size={{lg: 6, md: 12, sm: 12, xs: 12}}>
                    <Card sx={{flex: 1, cursor: "pointer"}} onClick={() => navigate(eventsRouteUrl)}>
                        <CardContent
                            sx={{display: "flex", flexDirection: "column", width: "100%", alignContent: "center"}}>
                            <Typography variant={"h4"} textAlign={"left"} padding={0}>
                                События
                            </Typography>
                            <Typography variant={"subtitle2"} textAlign={"left"} paddingTop={4} paddingBottom={0}
                                        color={"textSecondary"}>
                                {prepareTest(ctx.texts.get("menu.events.description"))}
                            </Typography>
                        </CardContent>
                        <CardActions>
                            <Link to={eventsRouteUrl}>Показать</Link>
                        </CardActions>
                    </Card>
                </Grid>
                <Grid size={{lg: 6, md: 12, sm: 12, xs: 12}}>
                    <Card sx={{flex: 1, cursor: "pointer"}} onClick={() => navigate(aboutRouteUrl)}>
                        <CardContent
                            sx={{display: "flex", flexDirection: "column", width: "100%", alignContent: "center"}}>
                            <Typography variant={"h4"} textAlign={"left"} padding={0}>
                                О проекте
                            </Typography>
                            <Typography variant={"subtitle2"} textAlign={"left"} paddingTop={4} paddingBottom={0}
                                        color={"textSecondary"}>
                                {prepareTest(ctx.texts.get("menu.about.description"))}
                            </Typography>
                        </CardContent>
                        <CardActions>
                            <Link to={aboutRouteUrl}>Показать</Link>
                        </CardActions>
                    </Card>
                </Grid>
            </Grid>
        </Container>

        {!(mainTopic?.data?.attributes.places.data) ? null :
            <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                <Container sx={{
                    [theme.breakpoints.down("sm")]: {padding: 0},
                }}>
                    <Stack spacing={4} paddingTop={4} paddingBottom={4} sx={{
                        alignItems: "center",
                        [theme.breakpoints.down("md")]: {paddingTop: 4},
                        [theme.breakpoints.down("sm")]: {paddingTop: 2},
                    }}>
                        <Typography sx={{  [theme.breakpoints.down("sm")]: {paddingLeft: 2},}}
                            variant={"h2"}>{prepareTest(ctx.texts.get("page.main.sections.section1.title.primary")) || "Впервые в Омске? Собрали топ-30 достопримечательностей!"}</Typography>
                        <Typography variant={"body2"} textAlign={"center"} padding={0}
                                    sx={{[theme.breakpoints.down('md')]: {paddingLeft: 2, paddingRight: 2}}}
                                    color={"textSecondary"}>

                            {prepareTest(ctx.texts.get("page.main.sections.section1.title.secondary")) ||
                                <span>Влюбляем в город моментально!</span>}
                        </Typography>
                    </Stack>
                    <Grid container rowSpacing={4} columnSpacing={4} paddingTop={4} paddingBottom={4}
                          flexDirection={"row"} flexWrap={"wrap"}>
                        {topics.map(it =>
                            <Grid size={{md: 4, sm: 6, xs: 12}} ref={(el) => {
                                el && it.id ? cardsRef.current.set(it.id, el) : cardsRef.current.delete(it.id)
                            }}>
                                <Card sx={{
                                    height: "100%",
                                    position: "relative",
                                    paddingBottom: 6,
                                    cursor: "pointer",
                                    [theme.breakpoints.down("sm")]: {background: "none"}
                                }}
                                      onClick={() => navigate(generatePath(topicPlaceRoute, {
                                          id: `${it.id || ''}`,
                                          tId: `${mainTopicId || ''}`
                                      }))}>
                                    <Box sx={{width: "100%", aspectRatio: "37 / 22"}}>
                                        <CardMedia
                                            src={(it.attributes.pictures || []).length && it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url && `${baseUrl}/${it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url}` || ''}
                                            sx={{aspectRatio: "37 / 22"}}
                                            component="img"/>
                                    </Box>
                                    <CardContent>
                                        <Stack spacing={2} paddingTop={2}>
                                            <Typography variant={"h6"}>{it.attributes.caption || ''}</Typography>
                                            <Typography
                                                variant={"subtitle1"}
                                                color={"textSecondary"}>{it.attributes.description || ''}</Typography>
                                        </Stack>
                                    </CardContent>
                                    <CardActions sx={{bottom: 0, position: "absolute"}}>
                                        <Link to={generatePath(topicPlaceRoute, {
                                            id: `${it.id || ''}`,
                                            tId: `${mainTopicId || ''}`
                                        })}>Показать</Link>
                                    </CardActions>
                                    <Box sx={{position: "absolute", right: "0", bottom: "0", zIndex: 1}}>
                                        <Star/>
                                    </Box>
                                </Card>
                            </Grid>)
                        }
                    </Grid>

                    {mainTopic && <MyLink to={generatePath(topicRouteUrl, {id: `${mainTopicId}`})}>
                        {t('page.main.actions.alllocation.title', {name: mainTopic?.data?.attributes.caption})}
                    </MyLink>}
                </Container>
            </Paper>}

        {!(mainTopic2?.data?.attributes.places.data) ? null :
            <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                <Container sx={{
                    [theme.breakpoints.down("sm")]: {padding: 0},
                }}>
                    <Stack spacing={4} paddingTop={4} paddingBottom={4} sx={{
                        alignItems: "center",
                        [theme.breakpoints.down("md")]: {paddingTop: 4},
                        [theme.breakpoints.down("sm")]: {paddingTop: 2},
                    }}>
                        <Typography
                            variant={"h2"}>{prepareTest(ctx.texts.get("page.main.sections.section2.title.primary")) || "111Живете здесь и исследуете город? Рекомендуем необычное"}</Typography>
                        <Typography variant={"body2"} textAlign={"center"} padding={0}
                                    sx={{[theme.breakpoints.down('md')]: {paddingLeft: 2, paddingRight: 2}}}
                                    color={"textSecondary"}>

                            {prepareTest(ctx.texts.get("page.main.sections.section2.title.secondary")) ||
                                <span>описание подборки с акцентом на омичей</span>}
                        </Typography>
                    </Stack>
                    <Grid container rowSpacing={4} columnSpacing={4} paddingTop={4} paddingBottom={4}
                          flexDirection={"row"} flexWrap={"wrap"}>
                        {topics2.map(it =>
                            <Grid size={{md: 4, sm: 6, xs: 12}} ref={(el) => {
                                el && it.id ? cardsRef.current.set(it.id, el) : cardsRef.current.delete(it.id)
                            }}>
                                <Card sx={{
                                    height: "100%",
                                    position: "relative",
                                    paddingBottom: 6,
                                    cursor: "pointer",
                                    [theme.breakpoints.down("sm")]: {background: "none"}
                                }}
                                      onClick={() => navigate(generatePath(topicPlaceRoute, {
                                          id: `${it.id || ''}`,
                                          tId: `${mainTopicId2 || ''}`
                                      }))}>
                                    <Box sx={{width: "100%", aspectRatio: "37 / 22"}}>
                                        <CardMedia
                                            src={(it.attributes.pictures || []).length && it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url && `${baseUrl}/${it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url}` || ''}
                                            sx={{aspectRatio: "37 / 22"}}
                                            component="img"/>
                                    </Box>
                                    <CardContent>
                                        <Stack spacing={2} paddingTop={2}>
                                            <Typography variant={"h6"}>{it.attributes.caption || ''}</Typography>
                                            <Typography
                                                variant={"subtitle1"}
                                                color={"textSecondary"}>{it.attributes.description || ''}</Typography>
                                        </Stack>
                                    </CardContent>
                                    <CardActions sx={{bottom: 0, position: "absolute"}}>
                                        <MyLink to={generatePath(topicPlaceRoute, {
                                            id: `${it.id || ''}`,
                                            tId: `${mainTopicId2 || ''}`
                                        })}>Показать</MyLink>
                                    </CardActions>
                                    <Box sx={{position: "absolute", right: "0", bottom: "0", zIndex: 1}}>
                                        <Star/>
                                    </Box>
                                </Card>
                            </Grid>)
                        }
                    </Grid>
                    {mainTopic2 &&
                        <MyLink to={generatePath(topicRouteUrl, {id: `${mainTopicId2}`})}>
                            {t('page.main.actions.alllocation.title', {name: mainTopic2?.data?.attributes.caption})}
                        </MyLink>}
                </Container>
            </Paper>}

        <ApplicationFooter/>
    </div>
}

export default MainPage;