import {Box, Dialog, IconButton} from "@mui/material";
import React, {useContext, useState} from "react";
import {AppContext} from "../app-context/app-context.component";
import {Qr} from "./qr-code.component";

export interface QrDialogProps {
    children: React.ReactNode,
    url?: string | null,
    anchor?: boolean
}

export const QrLink = (props: QrDialogProps) => {

    const ctx = useContext(AppContext);
    const [showQr, setShowQr] = useState(false);
    if (!props.url) {
        return null
    }

    const handleClick = (e: React.SyntheticEvent) => {
        e.preventDefault();
        if (ctx.kiosk) {
            setShowQr(true)
        } else {
            window.open(props.url || '', "blank")
        }
    }

    return <>
        {!props.anchor && <IconButton sx={{marginTop: 0}} onClick={handleClick}>
            {props.children}
        </IconButton>}
        {props.anchor && <a href={props.url} onClick={handleClick}>
            {props.children}
        </a>}
        {showQr && <Dialog open={showQr} onClose={() => setShowQr(false)}>
            <Box padding={4}>
                <Qr url={props.url}/>
            </Box>
        </Dialog>}
    </>
}