import React from 'react';
import './App.css';
import MainPage from "./pages/main-page/main-page.component";
import {ThemeProvider} from "@mui/material/styles";
import CssBaseline from "@mui/material/CssBaseline";
import {darkTheme} from "./theme/dark.theme";
import {createBrowserRouter, createHashRouter, RouterProvider, useSearchParams} from "react-router";
import {
    aboutRouteUrl, baseRoute,
    eventItemRouteUrl,
    eventsRouteUrl,
    excursionItemRoute, excursionPlaceRoute,
    excursionRoute,
    placeRoute, topicPlaceRoute,
    topicRouteUrl,
    topicsRouteUrl
} from "./config/routes";
import ExcursionPage from "./pages/excursion-page/excursion-page.component";
import {ExcursionItemPage} from "./pages/excursion-item-page/excursion-item-page.component";
import {YMaps} from "@pbe/react-yandex-maps";
import {PlaceItemPage} from "./pages/place-item-page/place-item-page.component";
import TopicPage from "./pages/topic-page/topic-page.component";
import {TopicItemPage} from "./pages/topic-item-page/topic-item-page.component";
import EventPage from "./pages/events-page/events-page.component";
import {EventItemPage} from "./pages/event-item-page/events-item-page.component";
import {AboutPage} from "./pages/about-page/about-page.component";
import {MainContextLoader} from "./pages/main/main-context-loader";
import {AppContext} from "./components/app-context/app-context.component";

const router = createHashRouter([
    {
        path: baseRoute,
        element: <MainPage/>,
    },
    {
        path: excursionRoute,
        element: <ExcursionPage/>,
    },
    {
        path: excursionItemRoute,
        element: <ExcursionItemPage/>,
    }, {
        path: placeRoute,
        element: <PlaceItemPage/>,
    }, {
        path: excursionPlaceRoute,
        element: <PlaceItemPage/>,
    }, {
        path: topicPlaceRoute,
        element: <PlaceItemPage/>,
    }, {
        path: placeRoute,
        element: <PlaceItemPage/>,
    }, {
        path: topicsRouteUrl,
        element: <TopicPage/>,
    }, {
        path: topicRouteUrl,
        element: <TopicItemPage/>,
    }, {
        path: eventsRouteUrl,
        element: <EventPage/>,
    }, {
        path: eventItemRouteUrl,
        element: <EventItemPage/>,
    }, {
        path: aboutRouteUrl,
        element: <AboutPage/>,
    }, {
        path: "*",
        element: <MainPage/>,
    },
]);


function App() {

    const search = window.location.search;
    const searchParams = new URLSearchParams(search);


    if (searchParams?.get('_mode_')) {
        localStorage.setItem('APP_MODE', searchParams.get('_mode_')?.toUpperCase() === 'KIOSK' ? "KIOSK" : '');
        searchParams.delete('_mode_');
        window.location.search = searchParams.toString();
    }

    return (
        <AppContext.Provider value={{kiosk: localStorage.getItem("APP_MODE") === 'KIOSK'}}>
            <YMaps version={"2.1.79"}>
                <ThemeProvider theme={darkTheme}>
                    <CssBaseline/>
                    <MainContextLoader>
                        <RouterProvider router={router}/>
                    </MainContextLoader>
                </ThemeProvider>
            </YMaps>
        </AppContext.Provider>
    )
}

export default App;
