import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import i18next from "i18next";
import LocalStorageBackend from 'i18next-localstorage-backend'; // primary use cache
import Backend from 'i18next-chained-backend';
import HttpApi from 'i18next-http-backend';
import {TFunction} from "i18next/typescript/t";
import {mainUrl} from "./config/consts";
import {Main} from "./components/main-context/main";


window.addEventListener('beforeunload', (event) => {
    event.preventDefault();
    event.returnValue = '';
});

 i18next
    .use(Backend)
    .init({
        backend: {
            namespace: {} as any,
            backends: [
                LocalStorageBackend,  // primary backend
                HttpApi               // fallback backend
            ],
            backendOptions: [{
                expirationTime: 10 * 1000,
            }, {
                /* options for secondary backend */
                loadPath: mainUrl, // http load path for my own fallback,
                parse: (_data: string) => {
                    if (!_data){
                        return {};
                    }
                    const data = JSON.parse(_data) as Main;
                    const res = {} as any;
                    (data?.data?.attributes?.texts || []).forEach(it => {
                        res[it.code] = it.value;
                    })
                    return res;
                },
            }]
        }
    }, (error: any, t: TFunction) => {
        const root = ReactDOM.createRoot(
            document.getElementById('root') as HTMLElement
        );
        root.render(
            <React.StrictMode>
                <App/>
            </React.StrictMode>
        );
    });


// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();
