import {Main} from "./main";
import React from "react";
import {MediaField} from "../../common/image";
import {Author} from "../../common/author";

export interface MainContextData {
    original: Main,
    texts: Map<string, string>,
    mainTopicId: number,
    mainTopicId2: number,
    pictures: MainContextPicture[],
    authors: Author[],
    about: string
}

export interface MainContextPicture {
    id: number,
    image: MediaField
}

export const emptyContext = () => {
    return {
        original: {
            data: {
                id: -1,
                attributes: {
                    texts: []
                }
            }
        },
        texts: new Map<string, string>(),
        pictures:[],
        authors: [],
        mainTopicId: -1,
        mainTopicId2: -1,
        about: ''
    } as MainContextData;
}

export const MainContext = React.createContext<MainContextData>(emptyContext())