import React, {useState, useMemo, useContext, useEffect, useRef} from "react";
import {Box, styled} from "@mui/material";

import {Placemark, Polyline, Map as YMap, Clusterer, useYMaps} from "@pbe/react-yandex-maps";
import {Place} from "../../pages/excursion-item-page/model";
import {baseUrl} from "../../config/consts";


interface Coords {
    lat: number;
    lon: number;
}

export interface MapStyles {
}

interface MapProps {
    center: Coords;
    places: Place[];
    onPlaceClick: (place: Place) => any;
    style: MapStyles;
    className?: string
    zoom: number;
    isExcursion: boolean;
    route: [number, number][];
    disableControls?: boolean
}

interface Limits {
    minLat: number;
    maxLat: number;
    minLon: number;
    maxLon: number;
}

export const RootDiv = styled("div", {
    name: 'YandexMap',
    slot: 'root'
})(({theme}) => ({
    "& .Map-Hidder":{
        position: "absolute",
        right: 0,
        height: 40,
        width: 300,
        bottom: 0
    }
}))


export const YandexMap = (props: MapProps) => {

    useEffect(() => {
        const listener = (id?: number) => {
            const place = (props.places || []).find(it => it.id === id);
            place && props.onPlaceClick(place);
        }
        (window as any).___________________________________clickListener = listener
        return () => {
            delete (window as any).___________________________________clickListener
        };
    }, [props.places])

    const divDef = useRef<HTMLElement | null>(null);


    const [centerPos, setCenterPos] = useState<Coords>(props.center);
    const [zoomState, setZoomState] = useState<number>(props.zoom);
    const allPalaces: Place[] = useMemo(() => {
        return props.places || [];
    }, [props.places]);

    const [clName, setClName] = useState('');

    const limitations: Limits = useMemo(() => {
        return {
            minLat: allPalaces.length > 0 ?
                allPalaces.filter(it => it.attributes.lat).map((item) => Number(item.attributes.lat))
                    .reduce((prev, cur) => (prev < cur ? prev : cur)) : props.center.lat,
            maxLat: allPalaces.length > 0 ? allPalaces.filter(it => it.attributes.lat).map((item) => Number(item.attributes.lat))
                .reduce((prev, cur) => (prev > cur ? prev : cur)) : props.center.lat,
            minLon: allPalaces.length > 0 ? allPalaces.filter(it => it.attributes.lon).map((item) => Number(item.attributes.lon))
                .reduce((prev, cur) => (prev < cur ? prev : cur)) : props.center.lon,
            maxLon: allPalaces.length > 0 ? allPalaces.filter(it => it.attributes.lon).map((item) => Number(item.attributes.lon))
                .reduce((prev, cur) => (prev > cur ? prev : cur)) : props.center.lon
        };
    }, [allPalaces]);


    const navigateOnMap = (direction: string) => {
        return () => {
            const offset = 0.005 + (14 - zoomState) * 0.001;

            switch (direction) {
                case "top":
                    if (!(centerPos.lat - 0.01 > limitations.maxLat)) {
                        setCenterPos((prev) => ({lat: prev.lat + offset, lon: prev.lon}));
                    }
                    break;
                case "left":
                    if (!(centerPos.lon + 0.01 < limitations.minLon)) {
                        setCenterPos((prev) => ({lat: prev.lat, lon: prev.lon - offset}));
                    }
                    break;
                case "bottom":
                    if (!(centerPos.lat + 0.01 < limitations.minLat)) {
                        setCenterPos((prev) => ({lat: prev.lat - offset, lon: prev.lon}));
                    }
                    break;
                case "right":
                    if (!(centerPos.lon - 0.01 > limitations.maxLon)) {
                        setCenterPos((prev) => ({lat: prev.lat, lon: prev.lon + offset}));
                    }
                    break;
            }
        };
    };
    const incrZoom = () => {
        setZoomState((prev) => ++prev);
    };
    const decrZoom = () => {
        setZoomState((prev) => --prev);
    };

    const initDiv = (el:HTMLElement | null)=>{
        if (el && divDef.current!==el){
            el.addEventListener("click", (e)=>{
                if (e.target && (e.target as HTMLElement).tagName.toUpperCase()==='A'){
                    debugger;
                    e.stopPropagation();
                    e.preventDefault();
                }
            }, true );
        }
        divDef.current = el;
    }

    const extraProps = !props.disableControls && {
        restrictMapArea: true,
        suppressMapOpenBlock: true,
        suppressObsoleteBrowserNotifier: true,
        behaviors: [],
        controls: [],
    } || {};


    return (
        <RootDiv>
            <Box sx={{
                width: "100%",
                height: {
                    xs: 400,
                    sm: 500,
                    md: 600
                },
                position: "relative" as any,
            }}
            ref={(el:any)=>initDiv(el)}
            >


                <YMap
                    key={"sf"}
                    options={{
                        suppressMapOpenBlock: true,
                        suppressObsoleteBrowserNotifier: true,
                    }}
                    className={"Inn"}
                    theme={"dark"}
                    style={{
                        borderRadius: 10,
                        width: "100%",
                        height: "100%",
                    }}
                    state={{
                        center: [centerPos.lat, centerPos.lon],
                        zoom: zoomState,
                        ...extraProps
                    }}
                >
                    {props.isExcursion && (
                        <Polyline
                            geometry={props.route}
                            options={{
                                //balloonCloseButton: true,
                                strokeColor: "#ed4543",
                                strokeWidth: 8,
                                strokeOpacity: 0.5,
                            }}
                        />
                    )}
                    <Clusterer
                        options={{
                            preset: "islands#invertedVioletClusterIcons",
                            groupByCoordinates: false,
                        }}
                    >
                        {props.places.filter(it => it.attributes?.lat && it.attributes?.lon).map((it) => (
                            <Placemark
                                key={it.id}
                                className={'aaaa'}
                                options={{
                                    // Опции.
                                    // Необходимо указать данный тип макета.
                                    iconLayout: 'default#image',
                                    // Своё изображение иконки метки.
                                    iconImageHref: (it.attributes.pictures || []).length>0 && it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url && `${baseUrl}/${it.attributes.pictures[0].image?.data?.attributes?.formats?.small?.url}` || '',
                                    // Размеры метки.
                                    iconImageSize: [50, 50],
                                    iconImageOffset: [-12, -25],
                                    iconImageClipRect:[[0,0],[334,334]],
                                    hasBalloon: true,
                                    iconShape: {
                                        type: 'Circle',
                                        coordinates: [0, 0],
                                        radius: 10,

                                    } as any
                                }}
                                modules={['geoObject.addon.balloon']}
                                properties={(props.places || []).length>1? {
                                    balloonContent: `<div style="width: 300px; min-height: 300px;">
                                        <img style="width:300px; aspect-ratio: 25 / 17;" src="${`${baseUrl}/${it.attributes.pictures[0]?.image?.data?.attributes?.formats?.small?.url}`}"
                                        <div>
                                            <h2 style="font-size: 18px;">${it.attributes?.caption}</h2>
                                            <div>
                                                <button onclick="___________________________________clickListener(${it.id})">Показать</button>
                                            </div>
                                        </div>
                                    </div>`,
                                    balloonAutoPan: true,
                                }:{}}
                                geometry={[Number(it.attributes.lon), Number(it.attributes.lat)]}
                            />
                        ))}
                    </Clusterer>
                </YMap>
                <div className={"Map-Hidder"}></div>
            </Box>

        </RootDiv>
    );
};
