export const getRandomItems = <T>(collection: T[], count: number): T[] => {
    const res = [] as T[];
    const source = [...collection];
    for (let i = 0; i < count; i++) {
        if (source.length === 0) {
            break;
        }
        let randomIndex = Math.floor(Math.random() * source.length);
        res.push(source[randomIndex]);
        source.splice(randomIndex, 1);
    }
    return res;
}