import * as React from "react";

export const prepareTest = (val?: string | null)=>{
    if (!val){
        return "";
    }
    const res:React.ReactNode[] = []
    val.split("\n").forEach((it, idx)=>{
        if (idx>0){
            res.push(React.createElement("br"));
        }
        res.push(it);
    })
    return res;
}

export const toUpperCapitalise = (val?: string | null)=>{
    if (!val){
        return val;
    }

    return val[0].toUpperCase() + val.substring(1);
}