import * as React from "react";
import {useContext, useEffect, useState} from "react";
import {authorsUrl, baseUrl} from "../../config/consts";
import {IPageResponse, IResponse} from "../../common/response";
import {Author} from "../../common/author";
import {useNavigate} from "react-router";
import axios, {AxiosResponse} from "axios";
import {ApplicationBar} from "../../components/appbar/application-bar";
import {ReactComponent as TgIcon} from "../../svg/telegramm.svg";
import {ReactComponent as OkIcon} from "../../svg/ok.svg";
import {ReactComponent as VkIcon} from "../../svg/vk.svg";
import {
    Box,
    Button,
    Card,
    CardActions,
    CardContent,
    CardMedia,
    Container,
    Grid, IconButton,
    Paper,
    Stack,
    Typography, useTheme
} from "@mui/material";
import {ReactComponent as Star} from "../../svg/star.svg";
import {TravelExplore} from "@mui/icons-material";
import {prepareTest} from "../../utils/text-utils";
import {baseRoute} from "../../config/routes";
import {ApplicationFooter} from "../../components/appbar/application-footer";
import {MainContext} from "../../components/main-context/main-context";
import {ReactComponent as EffectiveLogo} from "../../svg/effective.svg";
import {ReactComponent as UiktLogo} from "../../svg/uiktlogo.svg";
import {ReactComponent as LabLogo} from "../../svg/lab.svg";
import {MyHelmet} from "../../components/helmet/my-helmet.component";
import {QrLink} from "../../components/qrcode/qr-dialog.component";

export interface AboutPageProps {

}


export const AboutPage = (props: AboutPageProps) => {

    const navigate = useNavigate();

    const theme = useTheme();

    const ctx = useContext(MainContext);

    const [data, setData] = useState<IPageResponse<Author>>({
        data: [],
        meta: {
            pagination: {
                page: 0,
                total: 0,
                pageCount: 0,
                pageSize: 0
            }
        }
    });


    useEffect(() => {
        axios.get(authorsUrl, {
            params: {
                populate: "cover"
            }
        }).then((response: AxiosResponse<IPageResponse<Author>>) => {
            const data = response.data;
            const idxMap = new Map<number, number>();
            (ctx.authors || []).forEach((it, idx) => {
                idxMap.set(it.id, idx + 1);
            })
            data.data.sort((t1, t2) => (idxMap.get(t1.id) || 0) - (idxMap.get(t2.id) || 0))
            setData(data);
        }).catch((error) => navigate(baseRoute));
    }, [])

    if (data.data.length === 0) {
        return null;
    }


    return <div>
        <MyHelmet title={'О проекте'}/>
        <div style={{position: "relative"}}>
            <div style={{
                opacity: 0.03,
                position: "absolute",
                height: "100%",
                width: "100%",
                backgroundImage: "url(https://sun1-16.userapi.com/impg/7MVdJ7k4B_ik2HbKWyM68zx4gtGqYCNN1kJjaQ/p1oqti9iNfs.jpg?size=1600x1068&quality=96&sign=7fc8494393646b3ff6e56456854acce9&type=album)"
            }}>

            </div>
            <ApplicationBar/>
        </div>
        <Stack spacing={4} sx={{
            [theme.breakpoints.down("md")]: {paddingTop: 8, paddingBottom: 4},
            [theme.breakpoints.down("sm")]: {paddingTop: 8, paddingBottom: 4},

            paddingTop: 12,
            paddingBottom: 6
        }}>
            <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                <Container>
                    <Stack flexDirection={"row-reverse"} alignItems={"center"}>
                        <Stack spacing={4} sx={{
                            [theme.breakpoints.down("md")]: {paddingTop: 4},
                            [theme.breakpoints.down("sm")]: {paddingTop: 2},
                        }}>
                            <Typography variant={"h5"}>О проекте</Typography>
                            <Typography variant={"subtitle1"}
                                        color={"textSecondary"}>{prepareTest(ctx.about || '')}</Typography>
                        </Stack>
                    </Stack>

                </Container>
            </Paper>
            <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                <Container>
                    <Grid container={true}>
                        <Grid size={{lg: 4, xl: 4, sm: 6, xs: 6}} sx={{
                            display: "flex",
                            alignItems: "center",
                            alignContent: "center",
                            justifyContent: "center"
                        }}>
                            <UiktLogo width={"70%"}/>

                        </Grid>
                        <Grid size={{lg: 4, xl: 4, sm: 6, xs: 6}} sx={{
                            display: "flex",
                            alignItems: "center",
                            alignContent: "center",
                            justifyContent: "center"
                        }}>
                            <EffectiveLogo width={"70%"}/>
                        </Grid>
                        <Grid size={{lg: 4, xl: 4, sm: 12, xs: 12}}  sx={{
                            display: "flex",
                            alignItems: "center",
                            alignContent: "center",
                            justifyContent: "center"
                        }}>
                            <Grid size={{lg: 12, xl: 12, sm: 6, xs: 6}} sx={{
                                display: "flex",
                                alignItems: "center",
                                alignContent: "center",
                                justifyContent: "center"
                            }}>
                                <LabLogo width={"70%"}/>
                            </Grid>

                        </Grid>
                    </Grid>

                </Container>
            </Paper>

            <Paper style={{background: "unset"}} sx={{backgroundColor: "unset"}}>
                <Container>
                    <Typography
                        variant={"h5"}>{prepareTest(ctx.texts.get('page.about.titles.team') || 'Команда проекта')}</Typography>
                    <Grid container rowSpacing={4} columnSpacing={4} paddingTop={4} paddingBottom={4}
                          flexDirection={"row"} flexWrap={"wrap"}>
                        {(data.data || []).map(it =>
                            <Grid key={it.id} size={{
                                md: Math.max(4, 12 / data.data.length),
                                sm: Math.max(6, 12 / data.data.length),
                                xs: 12
                            }}>
                                <Card sx={{height: "100%", position: "relative", paddingBottom: 2}}>
                                    <CardMedia
                                        src={it.attributes?.photo?.data?.attributes?.formats?.small?.url ? `${baseUrl}/${it.attributes?.photo?.data?.attributes?.formats?.small?.url || ''}` : ''}
                                        sx={{aspectRatio: "37 / 22"}}
                                        component="img"/>
                                    <CardContent
                                        sx={[{
                                            display: {sm: "block", md: "flex"},
                                            flexDirection: "column",
                                            width: "100%"
                                        }]}>

                                        <Typography variant={"h6"} textAlign={"left"} paddingTop={2}
                                                    paddingBottom={0}>
                                            {it.attributes?.firstName || ''} {it.attributes?.lastName || ''}
                                        </Typography>
                                        {it.attributes?.roleText &&
                                            <Typography variant={"subtitle1"} textAlign={"left"} paddingTop={0}
                                                        color={"textSecondary"} fontSize={"90%"}
                                                        paddingBottom={2}>
                                                {it.attributes?.roleText || ''}
                                            </Typography> || ''}

                                        {it.attributes?.description ?
                                            <Typography variant={"subtitle1"} textAlign={"left"} color={"textSecondary"}
                                                        paddingTop={2}
                                                        paddingBottom={4}>
                                                {it.attributes?.description || ''}
                                            </Typography> : null}

                                    </CardContent>


                                    <CardActions sx={{bottom: 0, position: "absolute"}}>
                                        <Stack flexDirection={"row"} padding={1}>
                                            <QrLink url={it.attributes.externalLink}><TravelExplore style={{width: 24, height: 24}}/></QrLink>
                                            <QrLink url={it.attributes.tgLink}><TgIcon style={{width: 24, height: 24}}/></QrLink>
                                            <QrLink url={it.attributes.okLink}><OkIcon style={{width: 24, height: 24}}/></QrLink>
                                            <QrLink url={it.attributes.vkLink}><VkIcon style={{width: 24, height: 24}}/></QrLink>
                                        </Stack>
                                    </CardActions>
                                    <Box sx={{position: "absolute", right: "0", bottom: "0", zIndex: 1}}>
                                        <Star/>
                                    </Box>
                                </Card>
                            </Grid>)
                        }
                    </Grid>
                </Container>
            </Paper>
        </Stack>

        <ApplicationFooter/>
    </div>
}